Definition free_head_post (ra sp gp tp s0 s1 s2 s3 s4 s5 s6 s7 s8 s9 s10 s11 : word) (F : bvmap 5 word) (fc : bv 32)
    (m : mem) (lo U size b1 actx qcache TSD CTX TH sb TOP BOT : Z) (T : list Z) (d : depot) : machine_state -> Prop :=
  fun ms' => exists (t0 t1 t2 a5 a6 a7 t3 t4 t5 t6 : word) (jk : list byte) (rest : list word) m',
    ms' = MS (mkR (wz 0x54624) (Z_to_bv 64 (bv_unsigned sp + -2208)) gp tp t0 t1 t2 (wz (AINST + OI_Q)) (wz (TH + OT_TQ))
                  (wz (TH + OT_TQ)) (wz (TH + OT_CACHE)) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (U + -16)) (wz size) a5 a6 a7
                  (wz size) (Z_to_bv 64 (bv_unsigned sp + -2128)) (wz (TH + OT_CACHE)) (wz (U + -16)) (wz qcache) s7 s8 s9 s10 s11 t3 t4 t5 t6)
             F (Z_to_bv 64 0x54630) fc None m' (seg_rom bsegs)
    /\ munch (free_head_W lo (bv_unsigned sp) TH U size d) m m'
    /\ wmono bsegs m m' /\ mem_inv bsegs m'
    /\ IENV tp TSD CTX TH sb TOP BOT m'
    /\ stk bsegs m' lo (bv_unsigned sp + -2208)
    /\ rw_cells bsegs m' (bv_unsigned sp + -2208) (put_frame sp s6 U TH)
    (* [comment removed for export] *)
    /\ rw_cells bsegs m' (bv_unsigned sp + -2128) [C8 (wz (bv_unsigned sp + -2128 + 16)); C8 (wz (Z.of_nat (length T)))]
    /\ u64arr bsegs m' (bv_unsigned sp + -2128 + 16) (map wz T ++ rest) /\ length rest = (255 - length T)%nat
    /\ rw_cells bsegs m' (bv_unsigned sp + -72) [C8 sp]
    /\ rw_cells bsegs m' (bv_unsigned sp + -64) [CB 8 jk; C8 s5; C8 s4; C8 s3; C8 s2; C8 s1; C8 s0; C8 ra]
    /\ Forall (fun x => 0 <= x < 2^64) T /\ (1 <= length T <= 30)%nat
    (* [comment removed for export] *)
    /\ rw_cells bsegs m' (U + -16) [C1 (b8 3); C1 (b8 b1); C2 (wz 0); C4 (wz size); C8 (wz actx)]
    /\ rw_cells bsegs m' U [C8 (wz (d_putid d (depot_hash T)))]
